package com.macro.mall.security.component;
import cn.hutool.json.JSONUtil;
import com.macro.mall.common.api.CommonResult;
import org.springframework.security.core.AuthenticationException;
import org.springframework.security.web.AuthenticationEntryPoint;
import org.springframework.stereotype.Component;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
/**
 * 自定义返回结果：未登录或登录过期
 * Created by macro on 2018/5/14.
 */
public class RestAuthenticationEntryPoint implements AuthenticationEntryPoint {
    @Override
    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException authException) throws IOException, ServletException {
        response.setHeader("Access-Control-Allow-Origin", "*");
        response.setHeader("Cache-Control","no-cache");
        response.setCharacterEncoding("UTF-8");
        response.setContentType("application/json");
        response.getWriter().println(JSONUtil.parse(CommonResult.unauthorized(authException.getMessage())));
        response.getWriter().flush();
    }
}

**Is your feature request related to a problem? Please describe.**
The SM3, SM4 and SHA512 hashing instructions are not currently supported in Ghidra. These instructions are used to accelerate calculating hashes with these algorithms.

Example:
```
int main () {
    // SHA512
    asm("VSHA512MSG1 %xmm0, %ymm1");
    asm("VSHA512MSG2 %ymm0, %ymm1");
    asm("VSHA512RNDS2 %xmm0, %ymm1, %ymm2");
    // SM3
    asm("VSM3MSG1 (%rax), %xmm1, %xmm2");
    asm("VSM3MSG1 %xmm0, %xmm1, %xmm2");
    asm("VSM3MSG2 (%rax), %xmm1, %xmm2");
    asm("VSM3MSG2 %xmm0, %xmm1, %xmm2");
    asm("VSM3RNDS2 $0, %xmm1, %xmm2, %xmm3");
    asm("VSM3RNDS2 $0, (%rax), %xmm2, %xmm3");
    // SM4
    asm("VSM4KEY4 %xmm0, %xmm1, %xmm2");
    asm("VSM4KEY4 (%rax), %xmm1, %xmm2");
    asm("VSM4KEY4 %xmm20, %xmm21, %xmm22");
    asm("VSM4KEY4 (%rax), %xmm21, %xmm22");
    asm("VSM4KEY4 %ymm0, %ymm1, %ymm2");
    asm("VSM4KEY4 (%rax), %ymm1, %ymm2");
    asm("VSM4KEY4 %ymm20, %ymm21, %ymm22");
    asm("VSM4KEY4 (%rax), %ymm21, %ymm22");
    asm("VSM4KEY4 %zmm20, %zmm21, %zmm22");
    asm("VSM4KEY4 (%rax), %zmm21, %zmm22");
    asm("VSM4RNDS4 %xmm0, %xmm1, %xmm2");
    asm("VSM4RNDS4 (%rax), %xmm1, %xmm2");
    asm("VSM4RNDS4 %xmm20, %xmm21, %xmm22");
    asm("VSM4RNDS4 (%rax), %xmm21, %xmm22");
    asm("VSM4RNDS4 %ymm0, %ymm1, %ymm2");
    asm("VSM4RNDS4 (%rax), %ymm1, %ymm2");
    asm("VSM4RNDS4 %ymm20, %ymm21, %ymm22");
    asm("VSM4RNDS4 (%rax), %ymm21, %ymm22");
    asm("VSM4RNDS4 %zmm20, %zmm21, %zmm22");
    asm("VSM4RNDS4 (%rax), %zmm21, %zmm22");
    return 0;
}
